withinTransaction(async () => {
  const tracks = song.tracks;
  const totalBeats = 960; // 8 minutes at 120 BPM

  // Create initial clip for Kick
  await tracks[0].createMidiClip(0, 32); // Kick, initial 8-bar clip

  // Extend all clips to totalBeats
  const clipNames = ["Kick", "Drums", "Bass", "Chords", "Pads"];
  for (let i = 0; i < clipNames.length; i++) {
    const track = tracks[i];
    const clip = track.arrangementClips[0]; // Assuming only one clip per track for now
    if (clip) {
      clip.length = totalBeats;
    }
  }
});

